function renderCheckinList(checkIns){if(!els.checkinList)return;els.checkinList.innerHTML="";if(!checkIns.length){const empty=document.createElement("div");empty.className="empty-state";empty.textContent="本周还没有打卡项，先添加一个目标吧。";els.checkinList.appendChild(empty);return}checkIns.slice().sort((a,b)=>{if(Boolean(a?.isCompleted)!==Boolean(b?.isCompleted))return a?.isCompleted?1:-1;return String(a?.name||"").localeCompare(String(b?.name||""),"zh-CN")}).forEach(item=>{const card=createCheckinCardElement(item);els.checkinList.appendChild(card)})}
